<template>
  <ion-page><main class="login-page"><section class="brand-panel"><div class="seal"><ion-icon :icon="schoolOutline"/></div><div><p class="eyebrow">PHINMA EDUCATION</p><h1>Uniform Request<br>Portal</h1><p class="brand-copy">A simpler way to request, track, and collect official school uniforms.</p></div><div class="trust"><ion-icon :icon="shieldCheckmarkOutline"/><span>Secure university services</span></div></section><section class="login-panel"><div class="login-box"><div class="mobile-brand"><ion-icon :icon="schoolOutline"/><b>PHINMA</b></div><p class="eyebrow green">{{role==='student'?'STUDENT PORTAL':'MARKETING OFFICE'}}</p><h2>Welcome back</h2><p class="sub">Sign in to continue to your {{role==='student'?'student account':'workspace'}}.</p><form autocomplete="on" @submit.prevent="submit"><label>{{role==='student'?'Student ID':'Employee ID'}}</label><div class="field"><ion-icon :icon="personOutline"/><ion-input v-model="identifier" name="username" autocomplete="username" :placeholder="role==='student'?'e.g. 01-2526-123456':'e.g. 01-2526-12345'"/></div><label>Password</label><div class="field"><ion-icon :icon="lockClosedOutline"/><ion-input v-model="password" name="password" autocomplete="current-password" :type="show?'text':'password'" placeholder="Enter your password"/><button class="eye" type="button" @click="show=!show"><ion-icon :icon="show?eyeOffOutline:eyeOutline"/></button></div><p v-if="message" class="error">{{message}}</p><ion-button expand="block" type="submit" :disabled="loading||!identifier||password.length<4"><ion-spinner v-if="loading"/><span v-else>Sign in securely</span></ion-button></form><div class="switch">{{role==='student'?'Marketing Office staff?':'Are you a student?'}} <router-link :to="role==='student'?'/marketing/login':'/student/login'">Open {{role==='student'?'staff':'student'}} login</router-link></div></div></section></main></ion-page>
</template>
<script setup lang="ts">
import{computed,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{IonButton,IonIcon,IonInput,IonPage,IonSpinner}from'@ionic/vue';import{schoolOutline,shieldCheckmarkOutline,personOutline,lockClosedOutline,eyeOutline,eyeOffOutline}from'ionicons/icons';import{portal}from'../stores/portal';import type{Role}from'../app/models';
const route=useRoute(),router=useRouter(),role=computed(()=>route.params.role as Role),identifier=ref(''),password=ref(''),show=ref(false),loading=ref(false),message=ref('');
async function submit(){loading.value=true;message.value='';try{await portal.login(role.value,identifier.value,password.value);const destination=`/${role.value}/dashboard`;identifier.value='';password.value='';show.value=false;await router.replace(destination)}catch(e){message.value=e instanceof Error?e.message:'Unable to sign in.'}finally{loading.value=false}}
</script>
